import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Adaptive Behavior Engine","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/detection-engine/behavior.md","filePath":"openshield-xdp/detection-engine/behavior.md","lastUpdated":null}'),n={name:"openshield-xdp/detection-engine/behavior.md"};function l(o,e,r,d,h,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="adaptive-behavior-engine" tabindex="-1">Adaptive Behavior Engine <a class="header-anchor" href="#adaptive-behavior-engine" aria-label="Permalink to &quot;Adaptive Behavior Engine&quot;">​</a></h1><p>The Adaptive Behavior Engine is OpenShield-XDP&#39;s self-learning layer. Instead of relying only on static thresholds, it continuously learns what <em>your</em> traffic looks like and flags groups of sources that behave anomalously — with no ML model, no training phase, and no per-workload tuning. A game server, a banking API, and a VoIP cluster each get their own learned profile automatically.</p><p>It runs entirely in userspace on top of the per-source and per-port statistics the XDP program already collects, so it adds no measurable packet path cost.</p><h2 id="two-windows" tabindex="-1">Two windows <a class="header-anchor" href="#two-windows" aria-label="Permalink to &quot;Two windows&quot;">​</a></h2><h3 id="window-a-—-baselines-normal-traffic" tabindex="-1">Window A — Baselines (normal traffic) <a class="header-anchor" href="#window-a-—-baselines-normal-traffic" aria-label="Permalink to &quot;Window A — Baselines (normal traffic)&quot;">​</a></h3><p>While no attack is active, the engine learns:</p><ul><li><strong>Per-port profiles</strong> — for every destination port (≈ one workload), the packet-rate and average packet-size distributions, using exact online mean/variance (Welford) plus reservoir-sampled median/MAD for robust z-scores.</li><li><strong>Global traits</strong> — TTL distribution, packet-size variance, and inter- arrival timing regularity across all sources.</li></ul><p>Baselines persist to <code>/var/lib/openshield/state/behavior.json</code> every 60 seconds and on shutdown, so a loader restart does not reset learning.</p><h3 id="window-b-—-candidate-clusters-anomalies" tabindex="-1">Window B — Candidate clusters (anomalies) <a class="header-anchor" href="#window-b-—-candidate-clusters-anomalies" aria-label="Permalink to &quot;Window B — Candidate clusters (anomalies)&quot;">​</a></h3><p>When a source&#39;s rate deviates strongly from its port&#39;s learned baseline (or the port has never been seen at that rate with bot-like traits), the source becomes a <em>candidate</em>. Candidates that look alike — same destination port, packet size within 20%, TTL within 12 — are grouped into <strong>clusters</strong>.</p><p>Each cluster is continuously scored 0–100 with named, human-readable reasons:</p><table tabindex="0"><thead><tr><th>Signal</th><th>Points</th></tr></thead><tbody><tr><td>10+ hosts behaving identically</td><td>+15</td></tr><tr><td>Nearly identical packet sizes</td><td>+25</td></tr><tr><td>Machine-paced timing (low CV)</td><td>+20</td></tr><tr><td>Explosive growth (fast, large appearance)</td><td>+20</td></tr><tr><td>Far above the port&#39;s learned baseline</td><td>+15</td></tr><tr><td>Port behavior never observed before</td><td>+10</td></tr></tbody></table><ul><li><strong>≥ 70 → suspicious</strong> — timeline entry, log line, Discord alert.</li><li><strong>≥ 85 → malicious</strong> — same reporting, plus the auto-block action if enabled.</li></ul><p>Clusters idle for more than 30 seconds expire. A cluster that survives 10 minutes without being flagged is resolved as legitimate and its sources keep training the baselines — this is how the system adapts to genuine workload changes (a new game mode, a marketing launch) without manual intervention.</p><h2 id="learning-freeze-during-attacks" tabindex="-1">Learning freeze during attacks <a class="header-anchor" href="#learning-freeze-during-attacks" aria-label="Permalink to &quot;Learning freeze during attacks&quot;">​</a></h2><p>While an attack is active, <strong>all learning stops</strong>. Attack traffic never contaminates the baselines — this prevents the classic &quot;slow climb&quot; bypass where a gradual flood inflates the baseline until it looks normal.</p><p>Attack-time traffic is analyzed separately by the forensics pipeline: every attack gets a fingerprint (<code>fingerprint.txt</code> / <code>fingerprint.json</code> in the attack&#39;s forensics directory) with an <strong>attack family classification</strong>:</p><ul><li><code>udp amplification (reflected)</code> — one dominant source port, fixed sizes</li><li><code>tcp syn flood</code> — ≥90% bare SYN packets</li><li><code>syn-ack reflection</code> — mostly SYN-ACKs (your address was spoofed)</li><li><code>botnet flood (fixed-size)</code> — uniform packet size, machine pacing</li><li><code>spoofed/randomized sources</code> — TTL spread across all ranges</li><li><code>port scan</code> — many destination ports, tiny packets</li><li><code>udp/tcp/icmp flood</code> — protocol-level fallback</li><li><code>unknown/mixed</code> — no dominant signature</li></ul><p>The family and its evidence are included in the attack-end Discord alert.</p><h2 id="manual-vs-auto-blocking" tabindex="-1">Manual vs. auto blocking <a class="header-anchor" href="#manual-vs-auto-blocking" aria-label="Permalink to &quot;Manual vs. auto blocking&quot;">​</a></h2><p>By default the engine runs in <strong>manual mode</strong>: clusters are reported and you decide what to block (the attacks tab in the TUI offers one-click pattern blocking and IP blacklisting per attack).</p><p>With <code>behavior.auto_block: true</code>, clusters that cross the malicious threshold have their member IPs banned automatically for one hour.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">behavior</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # master switch</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  auto_block</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # default: manual review</span></span></code></pre></div><h2 id="suppression-scheduling" tabindex="-1">Suppression scheduling <a class="header-anchor" href="#suppression-scheduling" aria-label="Permalink to &quot;Suppression scheduling&quot;">​</a></h2><p>If you know a legitimate traffic spike is coming (product launch, match start, seasonal peak), schedule a window in which the automatic machinery stands down so the surge neither poisons baselines nor gets auto-blocked:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Pause baseline learning for 2 hours</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suppress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2h</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Pause auto pattern/IP blocking for 90 minutes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suppress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auto-block</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 90m</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Show active windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Remove a window (or all of them)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span></span></code></pre></div><p>Schedules persist across loader restarts (<code>/var/lib/openshield/state/schedule.json</code>) and expire automatically.</p><h2 id="inspecting-the-engine" tabindex="-1">Inspecting the engine <a class="header-anchor" href="#inspecting-the-engine" aria-label="Permalink to &quot;Inspecting the engine&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> behavior</span></span></code></pre></div><p>prints the live state: learned per-port baselines (observations, median PPS, average size) and every active cluster with its confidence score and reasons. Cluster state changes also appear on the dashboard timeline and in the log feed.</p><h2 id="why-not-ml" tabindex="-1">Why not ML? <a class="header-anchor" href="#why-not-ml" aria-label="Permalink to &quot;Why not ML?&quot;">​</a></h2><p>ML-based detection needs labeled training data, periodic retraining, and still produces unexplained verdicts. The behavior engine uses robust online statistics instead:</p><ul><li><strong>No training phase</strong> — useful from the first minute, fully adapted within hours.</li><li><strong>Explainable</strong> — every verdict lists the exact reasons (&quot;nearly identical packet sizes&quot;, &quot;machine-paced timing&quot;).</li><li><strong>Self-correcting</strong> — unflagged clusters are re-absorbed as legitimate; expired state is garbage-collected.</li><li><strong>Cheap</strong> — a few hundred microseconds of CPU per refresh interval; zero cost in the packet path.</li></ul>`,33)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
